import { FSRSValidationError } from "./error.mjs";
import { Rating, parse, ratingSchema } from "@open-spaced-repetition/srs-kit";

//#region src/reschedule/reschedule.ts
/**
* Replays a review history on top of an existing srs-kit scheduler core.
*
* The scheduler instance keeps the model and chronology coupled, allowing the
* review-time, card and memory-state types to be inferred from the selected
* core.
*/
var Reschedule = class {
	scheduler;
	constructor(scheduler) {
		this.scheduler = scheduler;
	}
	/**
	* Rebuilds model memory from the review history and returns the memory state
	* after each review.
	*/
	replay(input, options = {}) {
		const reviews = this.prepareReviews(input.history, options);
		const memoryStates = this.scheduler.model.forward({
			history: this.toModelHistory(reviews),
			initialState: input.initialState
		});
		return {
			memoryState: memoryStates[memoryStates.length - 1],
			memoryStates
		};
	}
	/**
	* Replays the review history through the scheduler and returns the card and
	* revlog produced by each review.
	*/
	reschedule(input, options = {}) {
		const history = this.prepareReviews(input.history, options);
		const results = this.scheduler.forward({
			history,
			initialCard: input.initialCard
		});
		return {
			results,
			card: results[results.length - 1].card
		};
	}
	prepareReviews(history, { sortHistory = true }) {
		const reviews = [];
		const { chrono: chronoDefinition } = this.scheduler.definition;
		for (const review of history) {
			const rating = parse(ratingSchema, review.rating);
			if (rating === Rating.Manual) continue;
			reviews.push({
				rating,
				reviewTime: parse(chronoDefinition.schema.time, review.reviewTime)
			});
		}
		if (reviews.length === 0) throw new FSRSValidationError("Reschedule requires at least one non-manual review");
		const compare = this.scheduler.chrono.compare;
		if (sortHistory && compare) reviews.sort((left, right) => compare(left.reviewTime, right.reviewTime));
		return reviews;
	}
	toModelHistory(history) {
		const modelHistory = new Array(history.length);
		modelHistory[0] = {
			rating: history[0].rating,
			deltaT: 0
		};
		for (let index = 1; index < history.length; index++) {
			const deltaT = this.scheduler.chrono.difference(history[index - 1].reviewTime, history[index].reviewTime);
			if (!Number.isFinite(deltaT) || deltaT < 0) throw new FSRSValidationError("Review times must produce finite non-negative intervals");
			modelHistory[index] = {
				rating: history[index].rating,
				deltaT
			};
		}
		return modelHistory;
	}
};

//#endregion
export { Reschedule };